describe('Authentication - Incorrect Password Error Message', () => {
  const validEmail = 'testuser@example.com';
  const incorrectPassword = 'wrongpassword123';
  const correctPassword = 'correctpassword123';
  const loginUrl = 'http://localhost:3000/login';
  const errorMessageSelector = '[data-testid="error-message"]';
  const emailInputSelector = '[data-testid="email-input"]';
  const passwordInputSelector = '[data-testid="password-input"]';
  const loginButtonSelector = '[data-testid="login-button"]';

  beforeEach(() => {
    cy.visit(loginUrl);
  });

  it('should display error message when user enters incorrect password', () => {
    cy.get(emailInputSelector).type(validEmail);
    cy.get(passwordInputSelector).type(incorrectPassword);
    cy.get(loginButtonSelector).click();

    cy.get(errorMessageSelector)
      .should('be.visible')
      .and('contain', 'Invalid email or password');
  });

  it('should display error message with specific text for multiple incorrect password attempts', () => {
    cy.get(emailInputSelector).type(validEmail);
    cy.get(passwordInputSelector).type(incorrectPassword);
    cy.get(loginButtonSelector).click();

    cy.get(errorMessageSelector)
      .should('be.visible')
      .and('have.text', 'Invalid email or password');

    cy.get(passwordInputSelector).clear().type('anotherincorrectpassword');
    cy.get(loginButtonSelector).click();

    cy.get(errorMessageSelector)
      .should('be.visible')
      .and('contain', 'Invalid email or password');
  });

  it('should not display error message when correct password is entered', () => {
    cy.get(emailInputSelector).type(validEmail);
    cy.get(passwordInputSelector).type(correctPassword);
    cy.get(loginButtonSelector).click();

    cy.get(errorMessageSelector).should('not.exist');
    cy.url().should('not.include', '/login');
  });

  it('should clear error message when user modifies password field after error', () => {
    cy.get(emailInputSelector).type(validEmail);
    cy.get(passwordInputSelector).type(incorrectPassword);
    cy.get(loginButtonSelector).click();

    cy.get(errorMessageSelector).should('be.visible');

    cy.get(passwordInputSelector).clear().type(correctPassword);

    cy.get(errorMessageSelector).should('not.be.visible');
  });
});
